function validate([grid]) {
  if (!Array.isArray(grid) || grid.length < 1 || grid.length > 10) return 'grid needs 1 to 10 rows.';
  const cols = grid[0].length;
  if (cols < 1 || cols > 10) return 'grid needs 1 to 10 columns.';
  if (grid.some(row => row.length !== cols)) return 'Every row of grid must have the same length.';
  if (grid.some(row => row.some(v => !Number.isInteger(v) || v < 0 || v > 15))) return 'Each value is an integer from 0 to 15.';
  return null;
}

