function numMagicSquaresInside(grid) {
  const rows = grid.length;
  const cols = grid[0].length;
  let count = 0;

  const isMagic = (top, left) => {
    if (grid[top + 1][left + 1] !== 5) {
      return false;
    }
    const seen = new Array(10).fill(false);
    for (let r = top; r < top + 3; r++) {
      for (let c = left; c < left + 3; c++) {
        const value = grid[r][c];
        if (value < 1 || value > 9 || seen[value]) {
          return false;
        }
        seen[value] = true;
      }
    }
    for (let i = 0; i < 3; i++) {
      const rowSum = grid[top + i][left] + grid[top + i][left + 1] + grid[top + i][left + 2];
      const colSum = grid[top][left + i] + grid[top + 1][left + i] + grid[top + 2][left + i];
      if (rowSum !== 15 || colSum !== 15) {
        return false;
      }
    }
    const diagonal = grid[top][left] + grid[top + 1][left + 1] + grid[top + 2][left + 2];
    const antiDiagonal = grid[top][left + 2] + grid[top + 1][left + 1] + grid[top + 2][left];
    return diagonal === 15 && antiDiagonal === 15;
  };

  for (let top = 0; top + 2 < rows; top++) {
    for (let left = 0; left + 2 < cols; left++) {
      if (isMagic(top, left)) {
        count++;
      }
    }
  }
  return count;
}

