function numMagicSquaresInside(grid) {
  let total = 0;
  for (let a = 0; a + 3 <= grid.length; a++) {
    for (let b = 0; b + 3 <= grid[0].length; b++) {
      const cell = (i, j) => grid[a + i][b + j];
      const values = [];
      for (let i = 0; i < 3; i++) for (let j = 0; j < 3; j++) values.push(cell(i, j));
      const sorted = [...values].sort((x, y) => x - y);
      if (sorted.join(',') !== '1,2,3,4,5,6,7,8,9') continue;
      const lines = [];
      for (let i = 0; i < 3; i++) {
        lines.push(cell(i, 0) + cell(i, 1) + cell(i, 2));
        lines.push(cell(0, i) + cell(1, i) + cell(2, i));
      }
      lines.push(cell(0, 0) + cell(1, 1) + cell(2, 2));
      lines.push(cell(0, 2) + cell(1, 1) + cell(2, 0));
      if (lines.every(s => s === lines[0])) total++;
    }
  }
  return total;
}

