function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  const loShu = [[4, 9, 2], [3, 5, 7], [8, 1, 6]];
  const rotate = m => m[0].map((_, j) => m.map(row => row[j]).reverse());
  const mirror = m => m.map(row => [...row].reverse());
  const variants = [];
  let square = loShu;
  for (let k = 0; k < 4; k++) { variants.push(square, mirror(square)); square = rotate(square); }
  // Blocks that look almost magic: repeated values, values shifted out of 1..9, or broken diagonals.
  const traps = [
    [[5, 5, 5], [5, 5, 5], [5, 5, 5]],
    loShu.map(row => row.map(v => v - 1)),
    loShu.map(row => row.map(v => v + 6)),
    [[1, 5, 9], [6, 7, 2], [8, 3, 4]],
    [[4, 9, 2], [7, 5, 3], [8, 1, 6]]
  ];
  const rows = size === 'large' ? 10 : 1 + pick(6);
  const cols = size === 'large' ? 10 : 1 + pick(6);
  const high = rand() < 0.5 ? 16 : 10;
  const grid = Array.from({ length: rows }, () => Array.from({ length: cols }, () => pick(high)));
  if (rows < 3 || cols < 3) return [grid];
  const plants = size === 'large' ? 4 + pick(8) : pick(4);
  for (let p = 0; p < plants; p++) {
    const block = rand() < 0.75 ? variants[pick(variants.length)] : traps[pick(traps.length)];
    const top = pick(rows - 2), left = pick(cols - 2);
    for (let i = 0; i < 3; i++) for (let j = 0; j < 3; j++) grid[top + i][left + j] = block[i][j];
  }
  return [grid];
}
